custom_css:
/* --- 梦境之地 (Dreamland) V2 感谢尾老师，类名，输入框伪提示词来自尾老师，hy老师的去除思维链箭头，na老师的悬浮底栏和思维链文字自定义，楼层信息自定义，12的去思维链背景色。感谢NA老师的去阴影，感谢咩野老师的去除全局阴影. --- */

/* --- 1. 字体导入 --- */
@import url('https://fonts.googleapis.com/css2?family=Great+Vibes&display=swap'); 
@import url('https://fontsapi.zeoseven.com/796/main/result.css'); 
@import url('https://fontsapi.zeoseven.com/253/main/result.css'); 

@font-face {
    font-family: 'Haishui';
    src: url('https://cdn.jsdelivr.net/gh/loud23for-ship-it/ziti@main/haishui.woff2') format('woff2');
    font-weight: normal;
    font-style: normal;
    font-display: swap;
}

@font-face {
    font-family: 'LingDong';
    src: url('https://cdn.jsdelivr.net/gh/loud23for-ship-it/ziti@main/lingdong.woff2') format('woff2');
    font-weight: normal;
    font-style: normal;
}

/* --- 2. 核心颜色与样式变量 --- */
:root {
    --theme-bg: #1a2235;
    --panel-bg-color: rgba(50, 78, 123, 0.85);
    --panel-bg-hover: rgba(80, 104, 169, 0.95);
    --card-bg: rgba(50, 78, 123, 0.65);
    --input-bg: rgba(28, 38, 56, 0.9);
    --text-main: #ebefff;
    --text-subtle: #86a6df;
    --border-color: rgba(134, 166, 223, 0.3);
    --accent-color: #86a6df;
    --selected-color: #5068a9;
    --font-english: 'Great Vibes', cursive;
    --font-main: 'Haishui', var(--font-english);
    --font-quote: 'LingDong', var(--font-english);
    --font-code: 'Hangeuljaemin4.0', monospace;
    --font-title: 'JasonHandwriting1', var(--font-english);
    --border-radius: 16px;
}

/* --- 3. 全局样式 (无阴影, 无边框) --- */
body { background-color: var(--theme-bg) !important; color: var(--text-main); font-family: var(--font-main); }
#sheld, #character_view { background: transparent !important; margin: 0 auto !important; left: 0; right: 0; border: none !important; box-shadow: none !important; overflow: visible !important; }
#chat { background: transparent !important; align-items: center !important; padding-bottom: 120px !important; }
h1, h2, h3, h4, .standoutHeader, .inline-drawer-header, .title_restorable { font-family: var(--font-title); color: var(--text-main); border: none !important; box-shadow: none !important; }
* { box-shadow: none !important; border-width: 0; }

/* --- 4. 顶部导航栏 & 挂件 --- */
#top-settings-holder { position:relative; background-color: var(--panel-bg-color); backdrop-filter: blur(8px); box-shadow: none; border: none; }
.drawer-icon.fa-fw::before { content: '' !important; font-size: 0 !important; }
.drawer-icon.fa-fw { width: 35px; height: 40px; background-size: contain; background-repeat: no-repeat; background-position: center; transition: transform 0.3s ease; }
.drawer-icon.fa-fw:hover { transform: scale(1.1); }

/* 【精准修复】导航栏全按钮贴图替换，组合ID与Class彻底覆盖 */
#ai-config-button .drawer-icon, .drawer-icon.fa-sliders, 
#advanced-formatting-button .drawer-icon, .drawer-icon.fa-font, 
#user-settings-button .drawer-icon, .drawer-icon.fa-user, 
#extensions-settings-button .drawer-icon, .drawer-icon.fa-cubes, 
#persona-management-button .drawer-icon, .drawer-icon.fa-face-smile {
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260227/g0QD/1614X1517/2026-02-27_110459.png/webp') !important;
}
#sys-settings-button .drawer-icon, .drawer-icon.fa-plug, 
#WI-SP-button .drawer-icon, .drawer-icon.fa-book-atlas, 
.drawer-icon.fa-image, .drawer-icon.fa-panorama, 
#character_popup_button .drawer-icon, .drawer-icon.fa-address-card, 
#table_database_settings_drawer .drawer-icon, .drawer-icon.fa-bars-progress {
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260227/fZyo/1654X1347/2026-02-27_110430.png/webp') !important;
}

/* 抽屉 & 弹窗背景图 */
.drawer-content, dialog.popup .popup-body, #dialogue_popup {
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260227/YvsG/2496X1508/_cgi-bin_mmwebwx-bin_webwxgetmsgimg__%26MsgID%3D4506987269918902439%26skey%3D%40crypt_5a237c93_9cdac4d1d45a9f4650d6ad9f0d036256%26mmweb_appid%3Dwx_webfilehelper.jpg/webp') !important;
    background-size: cover !important; 
    background-position: center !important; 
    border: none !important; 
    border-radius: var(--border-radius); 
}
dialog.popup .popup-body::before, #dialogue_popup::before { content: ''; position: absolute; top: 0; left: 0; right: 0; bottom: 0; background-color: rgba(26, 34, 53, 0.7); backdrop-filter: blur(5px); z-index: 0; }
dialog.popup .popup-body > *, #dialogue_popup > * { position: relative; z-index: 1; }

/* --- 5. 底部悬浮输入栏 --- */
#send_textarea::placeholder { color: transparent !important; opacity: 0 !important; }
#send_textarea::-webkit-input-placeholder { color: transparent !important; opacity: 0 !important; }
#form_sheld { position: absolute !important; bottom: 15px !important; left: 0; right: 0; display: flex; justify-content: center; z-index: 1000; pointer-events: none; }
#send_form { pointer-events: auto; width: 90% !important; max-width: 800px !important; margin: 0 auto !important; border-radius: 25px !important; background-color: var(--input-bg) !important; padding: 10px 15px !important; backdrop-filter: blur(10px) !important; border: none !important; transition: all 0.5s ease !important; position: relative; }
#send_form:hover { transform: translateY(-5px) !important; background-color: var(--panel-bg-hover) !important; }
#rightSendForm, #leftSendForm { gap: 10px; }
#send_textarea { clip-path: none !important; border: none !important; background: transparent !important; color: var(--text-main) !important; }
#nonQRFormItems:has(#send_textarea:placeholder-shown)::before { content: '旋转木马悠悠，梦境絮语悄悄...'; color: var(--text-subtle); position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%); font-family: var(--font-main); font-size: 0.5em; pointer-events: none; z-index: 10; white-space: nowrap; }

#options_button::before, #send_but::before, #send_form #extensionsMenuButton::before, #ai_retry_button::before, #auto_completion_button::before { display: none !important; }
#options_button, #send_but, #send_form #extensionsMenuButton, #ai_retry_button, #auto_completion_button { width: 32px; height: 32px; background-size: contain; background-repeat: no-repeat; background-position: center; transition: transform 0.2s ease; font-size: 0; border: none; background-color: transparent; }
#options_button:hover, #send_but:hover, #send_form #extensionsMenuButton:hover, #ai_retry_button:hover, #auto_completion_button:hover { transform: scale(1.1); }

/* 底栏贴图替换 */
#options_button, #ai_retry_button, #auto_completion_button { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260227/joCj/1764X1547/2026-02-27_110339.png/webp') !important; }
#send_form #extensionsMenuButton { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260227/QiwN/1291X1409/2026-02-27_110418.png/webp') !important; }
#send_but { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260227/NLPd/1211X1562/2026-02-27_110446.png/webp') !important; }

/* --- 6. 核心：梦境游园券布局与消息 --- */
.mes { display: flex; flex-direction: column; padding: 0 !important; margin: 45px auto 40px !important; width: 85%; max-width: 700px; background: transparent !important; border: none !important; box-shadow: none !important; overflow: visible !important; position: relative; pointer-events: auto !important; }

/* 【完美修复】门票名片区域：防拉伸居中 + 左右缺口门票特效 */
.mes .mesAvatarWrapper {
    display: block !important;
    width: 100%;
    height: 120px !important; 
    min-height: 120px !important;
    position: relative;
    z-index: 5;
    margin-bottom: 25px !important; 
    background: transparent !important;
    border: none !important;
    box-shadow: none !important;
    overflow: visible !important; /* 解除裁切，允许头像随意出界 */
}

.mes .mesAvatarWrapper::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0; bottom: 0;
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260227/73LA/2550X825/%E6%9C%AA%E6%A0%87%E9%A2%98-1.png/webp');
    background-size: cover !important; /* cover防拉伸变形 */
    background-position: center !important;
    border-radius: 12px;
    /* 门票凹凸缺口特效核心 */
    -webkit-mask-image: radial-gradient(circle at 0% 50%, transparent 16px, black 17px), radial-gradient(circle at 100% 50%, transparent 16px, black 17px);
    -webkit-mask-size: 51% 100%;
    -webkit-mask-repeat: no-repeat;
    -webkit-mask-position: left, right;
    z-index: 1;
}

/* 【完美修复】头像层级与位置（向右移、压在名片上方） */
.mes .avatar {
    position: absolute !important;
    top: -15px !important; 
    left: 20px !important; /* 向右移动，垫在左上角 */
    transform: rotate(-3deg) !important; 
    width: 95px !important; 
    height: 135px !important; 
    background-color: #FAFAFA !important;
    padding: 6px 6px 20px 6px !important; 
    border: 1px solid rgba(134,166,223,0.3) !important;
    box-shadow: 2px 5px 15px rgba(0,0,0,0.2) !important; /* 加点阴影更有拍立得质感 */
    z-index: 20 !important; /* 绝对高优先级，压在门票和底图上方 */
    display: flex !important; 
    align-items: center;
    justify-content: center;
    border-radius: 2px !important;
}
.mes .avatar img {
    width: 100% !important; height: 100% !important;
    object-fit: cover !important; 
    border-radius: 0 !important; border: none !important;
}

/* =========================================================
   【完美修复】正文底色区与页眉贴图严格分离，告别文字重叠！
   ========================================================= */
.mes .mes_block {
    background-color: var(--card-bg) !important; 
    border-radius: var(--border-radius);
    padding: 150px 30px 35px 30px !important; /* 预留出150px给顶部独立的贴图区域 */
    margin-top: 0 !important; 
    position: relative;
    border: none !important;
    overflow: visible !important; 
    min-height: 200px !important; 
}

/* 消息顶图化身为绝对定位的伪元素，盖在顶部，不会影响文字 */
.mes .mes_block::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 130px; /* 固定图片高度 */
    background-size: cover !important;
    background-position: center !important; 
    background-repeat: no-repeat !important; 
    border-radius: var(--border-radius) var(--border-radius) 0 0;
    z-index: 1;
    pointer-events: none;
}
.mes[is_user="false"] .mes_block::before {
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260227/Hmti/3328X2496/_cgi-bin_mmwebwx-bin_webwxgetmsgimg__%26MsgID%3D6118196284736475453%26skey%3D%40crypt_5a237c93_9cdac4d1d45a9f4650d6ad9f0d036256%26mmweb_appid%3Dwx_webfilehelper.jpg/webp') !important;
}
.mes[is_user="true"] .mes_block::before {
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260227/MGVI/3328X2496/_cgi-bin_mmwebwx-bin_webwxgetmsgimg__%26MsgID%3D7359806065121916793%26skey%3D%40crypt_5a237c93_9cdac4d1d45a9f4650d6ad9f0d036256%26mmweb_appid%3Dwx_webfilehelper.jpg/webp') !important;
}

.mes .mes_text, .mes_reasoning { position: relative; z-index: 5; background: transparent !important; border: none !important; padding: 0 !important; margin: 0 !important; }
#chat .mes .mes_reasoning_header { background: transparent !important; border: none !important; box-shadow: none !important; border-radius: 0; padding: 0 !important; margin-bottom: 10px !important; display: inline-flex !important; align-items: center !important; }
.mes_reasoning_arrow { display: none !important; }
.mes_reasoning_header h4, .mes_reasoning_header_title { font-size: 0 !important; visibility: hidden; }
.mes_reasoning_header h4::before, .mes_reasoning_header_title::before { content: '繁星闪烁，梦核推演中...'; font-family: var(--font-title); font-size: 14px !important; color: var(--accent-color); visibility: visible; }
.mes_reasoning { border-left: 3px solid var(--accent-color) !important; padding-left: 15px !important; margin-bottom: 20px !important; }
.mes .mes_text { line-height: 1.9; color: var(--text-main); }

/* 排版与文字特效系统 */
.mes_text h1, .mes_text h2, .mes_text strong, .mes_text b { font-family: var(--font-title); font-weight: normal; color: var(--text-main); }
.mes_text h2 { border-left: 4px solid var(--accent-color); padding-left: 15px; background: linear-gradient(to right, rgba(134, 166, 223, 0.15) 0%, transparent 100%); }
.mes_text em, .mes_text i { font-family: var(--font-quote); font-style: italic !important; color: var(--italics_text_color); background: rgba(50, 78, 123, 0.4); padding: 2px 6px; border-radius: 6px; }
.mes_text blockquote { background-color: rgba(28, 38, 56, 0.5); border-left: 4px solid var(--accent-color); padding: 12px 18px; border-radius: 4px 12px 12px 4px; color: var(--quote_text_color); }
.mes_text span.quote, .mes_text q, .mes_text .dialogue { font-family: var(--font-quote); color: var(--quote_text_color); }
.mes_text code { font-family: var(--font-code); background-color: rgba(28, 38, 56, 0.8) !important; color: var(--text-main) !important; border: none !important; }

/* =========================================================
   ✨ 名字、时间戳与编辑按钮(小铅笔) 悬浮在页眉图上方
   ========================================================= */
.mes .mesAvatarWrapper > .ch_name { display: none !important; }

.mes .mes_block > .ch_name {
    display: flex !important; 
    position: absolute;
    top: 20px !important; 
    left: 25px !important;
    right: 25px !important;
    width: auto !important;
    justify-content: space-between !important;
    align-items: flex-start !important;
    background: transparent !important;
    border: none !important;
    z-index: 10; 
}
.mes .ch_name > .flex-container { display: flex !important; align-items: center !important; gap: 10px !important; flex-wrap: wrap !important; }
.mes .ch_name .name_text { background: rgba(28, 38, 56, 0.55); padding: 2px 10px; border-radius: 6px; font-weight: bold; font-size: 14px !important; color: var(--text-main) !important; backdrop-filter: blur(2px); }
.mes .mes_timer { background: rgba(28, 38, 56, 0.55); padding: 2px 8px; border-radius: 6px; color: var(--text-main) !important; font-size: 12px !important; backdrop-filter: blur(2px); }

/* 小铅笔与功能按钮 */
.mes .mes_buttons, .mes .mes_edit_buttons {
    flex-direction: row-reverse;
    gap: 8px;
    position: static !important;
    opacity: 0.65;
    transition: opacity 0.3s ease;
    pointer-events: auto !important;
}
.mes:hover .mes_buttons, .mes:hover .mes_edit_buttons { opacity: 1; }
.mes .mes_buttons .mes_button, .mes .mes_edit_buttons .mes_button {
    background-color: rgba(28, 38, 56, 0.8) !important;
    backdrop-filter: blur(4px);
    color: var(--text-main) !important;
    padding: 6px !important;
    border-radius: 8px !important;
    cursor: pointer;
    border: none !important;
}
.mes .mes_buttons .mes_button:hover, .mes .mes_edit_buttons .mes_button:hover {
    background-color: var(--accent-color) !important;
    color: #1A1A1A !important;
    transform: scale(1.1);
}

/* =========================================================
   【完美修复】游园门票（楼层信息）放在头像右侧的名片里
   ========================================================= */
.mes .mesIDDisplay {
    position: absolute;
    top: 45px !important; 
    left: 140px !important; /* 相对于头像(宽度95+左侧20)的位置 */
    background: rgba(28, 38, 56, 0.65) !important;
    color: var(--text-main) !important; 
    font-family: var(--font-title); 
    font-size: 14px !important; 
    padding: 6px 14px !important;
    border-radius: 6px !important;
    border: 1px dashed var(--accent-color) !important; /* 加点检票口戳记的氛围感 */
    z-index: 100; 
    white-space: nowrap;
    transform: none !important;
    right: auto !important;
    line-height: 1 !important;
    pointer-events: none;
}
.mesIDDisplay::before { content: '梦境游园券 · 第 '; }
.mesIDDisplay::after { content: ' 张'; }

/* =========================================================
   多选/删除功能的勾选框
   ========================================================= */
.mes_checkbox {
    display: block !important;
    position: absolute !important;
    top: 25px !important;
    right: -30px !important; 
    width: 22px !important;
    height: 22px !important;
    z-index: 9999 !important;
    pointer-events: auto !important;
    opacity: 1 !important;
    cursor: pointer;
}

/* --- 全局UI无边框设置 --- */
.standoutHeader, .inline-drawer-header, .title_restorable, #extensions_settings2 > div, #extensions_settings > div, .openai_logit_bias_preset_form, details > summary, #power-user-options-block h4, #InstructSettingsColumn h4, #SystemPromptColumn h4, #ContextSettings h4, .persona_management_global_settings h4, #character_popup h4, #AdvancedFormatting h4, #rm_group_chats_block h4, div[name*='HandlingToggles'] h4, div[name*='MiscellaneousToggles'] h4 { background: var(--card-bg) !important; border: none !important; border-radius: 8px !important; padding: 8px 12px !important; margin-bottom: 8px !important; color: var(--text-main) !important; }
input[type="text"], input[type="number"], input[type="search"], textarea, select, .text_pole { background-color: var(--input-bg) !important; border: none !important; color: var(--text-main) !important; border-radius: 8px !important; }
.menu_button { background-color: var(--card-bg) !important; border: none !important; color: var(--text-main) !important; transition: all 0.2s ease; }
.menu_button:hover { background-color: var(--accent-color) !important; color: #1A1A1A !important; }
input[type="checkbox"]:checked::before { box-shadow: inset 1em 1em var(--accent-color) !important; }
.menu_button.active, .menu_button.world_set, .menu_button.fav_on, #left-nav-panel .menu_button.selected { background-color: var(--selected-color) !important; color: #fff !important; font-weight: bold; border: none !important; }

#typing_indicator { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260227/QiwN/1291X1409/2026-02-27_110418.png/webp') !important; background-size: contain !important; background-repeat: no-repeat !important; background-position: center !important; animation: pulse 1.5s infinite ease-in-out; border: none !important; height: 40px !important; width: 40px !important; margin: 10px auto !important; }
#typing_indicator .dot { display: none !important; }
@keyframes pulse { 0% { transform: scale(0.95); opacity: 0.7; } 50% { transform: scale(1.05); opacity: 1; } 100% { transform: scale(0.95); opacity: 0.7; } }

/* 手机端适配 */
@media (max-width: 768px) {
    .mes .avatar { left: 10px !important; width: 75px !important; height: 105px !important; top: -10px !important; }
    .mes .mesIDDisplay { left: 105px !important; top: 40px !important; font-size: 12px !important; padding: 4px 10px !important; }
    .mes_checkbox { right: 10px !important; top: -10px !important; } 
}

/* =========================================================
   【修复】删除消息确认对话框按钮
   ========================================================= */

/* 确保对话框本身可见且可交互 */
#dialogue_popup {
    z-index: 10000 !important;
    pointer-events: auto !important;
}

/* 修复删除确认按钮的样式和交互 */
#dialogue_del_mes_ok,
#dialogue_del_mes_cancel {
    display: inline-block !important;
    visibility: visible !important;
    opacity: 1 !important;
    pointer-events: auto !important;
    position: relative !important;
    z-index: 10001 !important;

    /* 按钮基础样式 */
    background-color: var(--card-bg) !important;
    color: var(--text-main) !important;
    border: 1px solid var(--border-color) !important;
    border-radius: 8px !important;
    padding: 10px 20px !important;
    margin: 10px 5px !important;
    cursor: pointer !important;
    font-family: var(--font-main) !important;
    font-size: 14px !important;
    transition: all 0.2s ease !important;
}

/* 删除按钮悬停效果（红色警告） */
#dialogue_del_mes_ok:hover {
    background-color: #d32f2f !important;
    color: #fff !important;
    transform: scale(1.05) !important;
    border-color: #d32f2f !important;
}

/* 取消按钮悬停效果 */
#dialogue_del_mes_cancel:hover {
    background-color: var(--accent-color) !important;
    color: #1A1A1A !important;
    transform: scale(1.05) !important;
    border-color: var(--accent-color) !important;
}

/* 确保对话框内所有内容都可交互 */
#dialogue_popup > *,
#dialogue_popup .popup-body > *,
#dialogue_popup button,
#dialogue_popup input {
    pointer-events: auto !important;
    position: relative !important;
